}

int main() {
    float *ref, *got, *dgot;
    int *dfails, fails = 0;
    cudaMalloc(&ref, 4 * 32 * 4); cudaMalloc(&got, 8 * 32 * 4); cudaMalloc(&dgot, 8 * 32 * 4);
    cudaMalloc(&dfails, 4);
    cudaMemcpy(dfails, &fails, 4, cudaMemcpyHostToDevice);

    ref_mma<<<1, 32>>>(ref, dfails);
    test_mma_explicit<<<1, 32>>>(got, dfails);
    cudaMemcpy(&fails, dfails, 4, cudaMemcpyDeviceToHost);
    float r[4 * 32], g[8 * 32];
    cudaMemcpy(r, ref, 4 * 32 * 4, cudaMemcpyDeviceToHost);
    cudaMemcpy(g, got, 4 * 32 * 4, cudaMemcpyDeviceToHost);
    int bad = 0;
    for (int i = 0; i < 4 * 32; ++i)
        if (fabsf(r[i] - g[i]) > 1.f) { bad++; if (bad < 5) printf("mma explicit: lane %d idx %d ref %.1f got %.1f\n", i % 32, i / 32, r[i], g[i]); }
    printf("Test1 (explicit mma): %s\n", bad == 0 ? "PASS" : "FAIL");

    // ldmatrix x4
    cudaMemset(dfails, 0, 4);
