    cudaMemcpy(&fails, dfails, 4, cudaMemcpyDeviceToHost);
    cudaMemcpy(g, dgot, 8 * 32 * 4, cudaMemcpyDeviceToHost);
    printf("Test2 (ldsm.x4 -> A frag): %s\n", fails == 0 ? "PASS" : "FAIL");
    if (fails) {
        for (int lane = 0; lane < 32; ++lane) {
