                   (float)(g2 * 16 + 2 * t2), (float)(g2 * 16 + 2 * t2 + 1),
                   (float)((g2 + 8) * 16 + 2 * t2), (float)((g2 + 8) * 16 + 2 * t2 + 1),
                   (float)(g2 * 16 + 2 * t2 + 8), (float)(g2 * 16 + 2 * t2 + 9),
                   (float)((g2 + 8) * 16 + 2 * t2 + 8), (float)((g2 + 8) * 16 + 2 * t2 + 9));
        }
    }

    // ldmatrix x2 trans
    cudaMemset(dfails, 0, 4);
    test_ldsm_x2_trans<<<1, 32>>>(dgot, dfails);
    cudaMemcpy(&fails, dfails, 4, cudaMemcpyDeviceToHost);
    cudaMemcpy(g, dgot, 8 * 32 * 4, cudaMemcpyDeviceToHost);
    printf("Test3 (ldsm.x2.trans -> B frag): %s\n", fails == 0 ? "PASS" : "FAIL");
    if (fails) {
        for (int lane = 0; lane < 16; ++lane) {
            int g2 = lane >> 2, t2 = lane & 3;
            printf("  lane %d (g%d t%d):", lane, g2, t2);
            for (int i = 0; i < 4; ++i) printf(" %.0f", g[4 * lane + i]);
            printf("  expect: %.0f %.0f %.0f %.0f\n",
                   (float)(2 * t2 * 8 + g2), (float)((2 * t2 + 1) * 8 + g2),
                   (float)((2 * t2 + 8) * 8 + g2), (float)((2 * t2 + 9) * 8 + g2));
        }
