    bad = 0;
    for (int i = 0; i < 4 * 32; ++i)
        if (fabsf(r[i] - g[i]) > 1.f) { bad++; if (bad < 5) printf("full: lane %d idx %d ref %.1f got %.1f\n", i % 32, i / 32, r[i], g[i]); }
    printf("Test4 (ldsm x4 + x2trans + mma): %s\n", bad == 0 ? "PASS" : "FAIL");
