    uint32_t a[4], b[2];
    // A[m][k] = m*16+k. lane holds (row g, cols 2t,2t+1), (row g+8, ...), k-halves 0 and 1
    __nv_bfloat16 a00 = __float2bfloat16((float)(g * 16 + 2 * t));
    __nv_bfloat16 a01 = __float2bfloat16((float)(g * 16 + 2 * t + 1));
    __nv_bfloat16 a10 = __float2bfloat16((float)((g + 8) * 16 + 2 * t));
